def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if not path.startswith('/'):
        path = cwd + '/' + path

    queue = split(path)
    current = []  # resolved path components; root is represented by empty list
    link_count = 0

    while queue:
        comp = queue.pop(0)
        if comp == '..':
            if current:
                current.pop()
            # if at root, stays at root
        else:
            current.append(comp)
            candidate = '/' + '/'.join(current)
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                current.pop()  # remove the component; it's replaced by the link target
                if target.startswith('/'):
                    new_parts = split(target)
                    queue = new_parts + queue
                else:
                    dir_path = '/' + '/'.join(current)
                    combined = dir_path + '/' + target
                    new_parts = split(combined)
                    queue = new_parts + queue

    if not current:
        return '/'
    return '/' + '/'.join(current)

